use crate::telemetry::{ModelCallSnapshot, TokenUsage};
use crate::{now_unix, Lodestar, Result};

impl Lodestar {
    /// Record one Lodestar-initiated model call (decompose/judge/draft_question)
    /// for observability. Best-effort, mirroring `mindleak-core`'s
    /// `record_tool_call`: a telemetry write failure is logged and swallowed so
    /// it can never change the result of the call it observes.
    pub fn record_model_call(
        &self,
        operation: &str,
        ok: bool,
        duration_ms: i64,
        model: Option<&str>,
        usage: Option<TokenUsage>,
    ) {
        let outcome = if ok { "ok" } else { "error" };
        if let Err(error) = self.store.record_model_call(
            now_unix(),
            operation,
            outcome,
            Some(duration_ms),
            model,
            usage,
        ) {
            eprintln!("lodestar: failed to record model-call telemetry for '{operation}': {error}");
        }
    }

    /// A point-in-time snapshot of every recorded model call.
    pub fn model_telemetry(&self) -> Result<ModelCallSnapshot> {
        self.store.model_telemetry()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::facade::test_support::engine;

    #[test]
    fn a_recorded_model_call_is_reflected_in_the_snapshot() {
        let lodestar = engine();

        lodestar.record_model_call(
            "decompose",
            true,
            42,
            Some("glm4:9b"),
            Some(TokenUsage {
                prompt_tokens: Some(10),
                completion_tokens: Some(5),
                total_tokens: Some(15),
            }),
        );

        let snapshot = lodestar.model_telemetry().unwrap();
        assert_eq!(snapshot.total_calls, 1);
        assert_eq!(snapshot.total_errors, 0);
        assert_eq!(snapshot.total_tokens, 15);
        assert_eq!(snapshot.by_operation[0].operation, "decompose");
    }

    #[test]
    fn a_failed_model_call_is_recorded_as_an_error_with_no_usage() {
        let lodestar = engine();

        lodestar.record_model_call("judge", false, 5, Some("glm4:9b"), None);

        let snapshot = lodestar.model_telemetry().unwrap();
        assert_eq!(snapshot.total_calls, 1);
        assert_eq!(snapshot.total_errors, 1);
        assert_eq!(snapshot.total_tokens, 0);
    }

    /// The whole point of "best-effort": a caller that just ran
    /// decompose/judge/draft_question gets its own result regardless of
    /// whether the telemetry write behind it landed. Sabotages the table so
    /// the write genuinely fails, rather than asserting the happy path and
    /// calling that proof of the failure path.
    #[test]
    fn a_telemetry_write_failure_does_not_propagate_to_the_caller() {
        let lodestar = engine();
        // `ensure_table`'s CREATE TABLE IF NOT EXISTS leaves this alone, so the
        // INSERT that follows fails on missing columns instead.
        lodestar
            .store()
            .sabotage_table_for_test("CREATE TABLE model_call_events (id INTEGER PRIMARY KEY)");

        // Must return normally (not panic) even though the write beneath it
        // cannot possibly succeed against the sabotaged schema.
        lodestar.record_model_call(
            "decompose",
            true,
            10,
            Some("glm4:9b"),
            Some(TokenUsage {
                prompt_tokens: Some(1),
                completion_tokens: Some(1),
                total_tokens: Some(2),
            }),
        );

        // Confirms the sabotage actually broke the write (otherwise this test
        // would trivially pass regardless of whether swallowing works): the
        // snapshot read against the same broken schema surfaces the failure
        // rather than silently reporting a call that in fact never landed.
        assert!(lodestar.model_telemetry().is_err());
    }
}
